using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor
{
    public static class LogisticsVerification
    {
        static int checks;static double start;static bool done;
        [InitializeOnLoadMethod]static void Resume(){if(SessionState.GetBool("LogisticsVerify",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Update;Application.logMessageReceived+=Log;}}
        public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Battle01.unity");SessionState.SetBool("LogisticsVerify",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Update;Application.logMessageReceived+=Log;EditorApplication.EnterPlaymode();}
        static void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){File.WriteAllText("logistics-verification-error.txt",message+"\n"+stack);SessionState.SetBool("LogisticsVerify",false);EditorApplication.Exit(1);}}
        static void Check(bool value,string label){checks++;if(!value)throw new Exception("Logistics test: "+label);Debug.Log("LOGISTICS_CHECK "+label);}
        static void Near(float a,float b,string label){Check(Mathf.Abs(a-b)<.01f,label);}
        static void Update()
        {
            if(done)return;if(EditorApplication.timeSinceStartup-start>100){Debug.LogError("Logistics verification timeout");return;}if(!EditorApplication.isPlaying||Time.time<.7f)return;
            done=true;try{Tests();File.WriteAllText("logistics-verification-result.txt",checks+" assertions passed");Debug.Log("LOGISTICS_VERIFY_PASS: "+checks+" assertions");SessionState.SetBool("LogisticsVerify",false);EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);}
        }
        static void Tests()
        {
            var live=UnityEngine.Object.FindObjectOfType<LogisticsWorld>();Check(live!=null&&live.world.Initialized,"scene initialized");Check(UnityEngine.Object.FindObjectOfType<LogisticsHUD>()!=null,"UGUI logistics panel configured");
            var root=new GameObject("Isolated logistics test");var world=root.AddComponent<BattleWorld>();world.enabled=false;world.setup=live.world.setup;world.players=new[]{"A","B"};world.currentPlayer="A";
            var log=root.AddComponent<LogisticsWorld>();log.enabled=false;log.world=world;log.truckPrefab=live.truckPrefab;
            var cg=new GameObject("collector");cg.transform.SetParent(root.transform);cg.transform.position=new Vector3(100,100);var c=cg.AddComponent<ResourceCollector>();c.settings.collectionInterval=1;c.settings.amountPerInterval=30;c.settings.storageLimit=50;c.Initialize();log.collectors.Add(c);c.Tick(.9f);Near(c.Stock,0,"no production before interval");c.Tick(.1f);Near(c.Stock,30,"interval batch production");c.Tick(2);Near(c.Stock,50,"storage cap pauses production");Near(c.Take(20),20,"take deducts source stock");c.Tick(1);Near(c.Stock,50,"production resumes after taking stock");
            var tg=UnityEngine.Object.Instantiate(live.truckPrefab,root.transform);tg.transform.position=c.transform.position;var t=tg.GetComponent<TransportTruck>();var u=t.Unit;u.unitId="test-truck";u.ownerId="A";u.Initialize();t.sourceCollector=c;
            var pg=new GameObject("city");pg.transform.SetParent(root.transform);pg.transform.position=new Vector3(101,100);var city=pg.AddComponent<RecoveryPoint>();city.ownerId="A";city.resourceStock=1000;var bg=new GameObject("other city");bg.transform.SetParent(root.transform);bg.transform.position=new Vector3(110,100);var other=bg.AddComponent<RecoveryPoint>();other.ownerId="B";other.resourceStock=200;
            world.units=new[]{u};world.points=new[]{city,other};world.Initialize();log.LoadAtSource(t);Near(t.Cargo,50,"collector loads truck");Near(c.Stock,0,"loading conserves source stock");float speed=tg.GetComponent<ArmyRoadMover>().Speed;u.Damage(u.Personnel*.25f);Near(t.Cargo,37.5f,"25 percent damage destroys 25 percent cargo");Near(tg.GetComponent<ArmyRoadMover>().Speed,speed,"damage does not reduce driving speed");log.Unload(t,other);Near(t.Cargo,37.5f,"enemy city cannot receive cargo");Near(other.resourceStock,200,"cities do not share resources");tg.transform.position=city.transform.position;log.Tick(.1f);Near(t.Cargo,0,"automatic unloading on city arrival");Near(city.resourceStock,1037.5f,"unloading adds only destination stock");
            t.Load(80);u.Eliminate();Near(t.Cargo,0,"destroyed truck loses all cargo");c.Damage(10000);Near(c.Stock,0,"destroyed collector loses inventory");Check(!c.Alive&&c.ownerId=="A","collector destroyed rather than captured");
            u.Initialize();t.sourceCollector=null;t.sourceCity=city;t.destinationCity=other;t.StartAutomatic();log.Tick(.1f);Check(!t.Automatic,"automatic task stops for hostile destination");
            world.setup.modes.SetMode(MouseCommandMode.RoadMarch);Check(!log.BuildFactory(city),"factory construction requires mode3");world.setup.modes.SetMode(MouseCommandMode.Interaction);log.factoryBuildSeconds=.1f;Check(log.BuildFactory(city),"city factory build accepted");Check(!log.BuildFactory(city),"duplicate pending factory denied");log.Tick(.2f);Check(city.hasFactory&&log.FactoryCount("A")==1,"factory attached to city");Check(!log.BuildFactory(city),"one factory per city");other.ownerId="A";log.factoryLimitPerPlayer=1;Check(!log.BuildFactory(other),"global player factory cap enforced");city.resourceStock=2000;Check(log.BuildTruck(city,null,ArmyEchelon.Battalion),"truck build accepts echelon");int before=world.units.Length;log.Tick(10);Check(world.units.Length==before+1,"manufactured truck registered in battle");var created=world.units[world.units.Length-1];Check(created.combatDefinition.echelon==ArmyEchelon.Battalion,"chosen echelon applied");Check(Array.IndexOf(world.setup.sceneArmies,created.GetComponent<ArmyRoadMover>())>=0,"manufactured truck registered in movement");city.resourceStock=1000;Check(log.BuildTruck(city),"second truck job accepted");int registered=world.units.Length;city.ownerId="B";log.Tick(10);Check(world.units.Length==registered,"captured city cancels former owner production");city.ownerId="A";
            var network=live.world.setup.roadMap.Network;RoadEdge autoEdge=network.Edges[0];foreach(var edge in network.Edges)if(RoadPoint.Distance(network.Nodes[edge.A],network.Nodes[edge.B])>1.5&&live.world.setup.freeMarchMap.waterMap.CanTraverse(network.Nodes[edge.A],network.Nodes[edge.B])){autoEdge=edge;break;}
            var startNode=network.Nodes[autoEdge.A];var endNode=network.Nodes[autoEdge.B];var autoTruck=created.GetComponent<TransportTruck>();created.Initialize();created.transform.position=new Vector3((float)startNode.X,(float)startNode.Y);c.transform.position=created.transform.position;c.Initialize();c.Tick(2);city.transform.position=new Vector3((float)endNode.X,(float)endNode.Y);city.interactionRadius=.1f;autoTruck.sourceCollector=c;autoTruck.sourceCity=null;autoTruck.destinationCity=city;autoTruck.StartAutomatic();log.Tick(.1f);Check(created.Motor.IsMoving&&autoTruck.Cargo>0,"automatic job loads and starts actual road motor");float delivered=autoTruck.Cargo;float cityBefore=city.resourceStock;created.Motor.Stop();created.transform.position=city.transform.position;log.Tick(.1f);Near(city.resourceStock,cityBefore+delivered,"automatic destination arrival unloads cargo");log.Tick(1.1f);Check(created.Motor.IsMoving,"automatic job starts return route");autoTruck.ManualOrder();Check(!autoTruck.Automatic,"manual order overrides automatic job");
            var siteg=new GameObject("site");siteg.transform.SetParent(root.transform);siteg.transform.position=new Vector3(100,100);var site=siteg.AddComponent<ResourceSite>();site.areaSize=new Vector2(2,2);log.collectorSettings.footprint=Vector2.one*.3f;Check(!log.CanPlace(site,new Vector2(102,100)),"whole footprint must fit resource site");
            var oldMap=world.setup.freeMarchMap;world.setup.freeMarchMap=null;Check(log.CanPlace(site,new Vector2(100,100)),"destroyed collector footprint can be reused");var rebuilt=log.BuildCollector(site,new Vector2(100,100),city);Check(rebuilt!=null&&rebuilt.Alive,"collector can be rebuilt");Check(!log.CanPlace(site,new Vector2(100,100)),"live collector footprint cannot overlap");world.setup.freeMarchMap=oldMap;
            live.world.setup.modes.SetMode(MouseCommandMode.Interaction);var ui=UnityEngine.Object.FindObjectOfType<LogisticsHUD>();ui.battleHUD.SelectPoint(live.world.points[0]);ui.SendMessage("Update");foreach(var drop in ui.GetComponentsInChildren<UnityEngine.UI.Dropdown>(true)){if(drop.gameObject.activeInHierarchy){drop.Show();drop.Hide();}}Check(true,"active logistics dropdowns open without runtime errors");var route=live.RouteTo(live.world.points[0].transform.position,live.world.points[1].transform.position,null,false);Check(route!=null&&route.Count>=2,"automatic route follows existing road graph");
            var chosen=new List<Vector2>{new Vector2(0,0),new Vector2(1,0),new Vector2(2,0)};var reverse=live.RouteTo(new Vector3(2,0),Vector3.zero,chosen,true);Check(reverse.Count==3&&reverse[1].X==1,"custom outbound route reversed for return");
            var testCombat=UnityEngine.Object.Instantiate(u.combatDefinition);testCombat.fullStrengthAttack=100;testCombat.attackRadius=1;testCombat.visionRadius=3;u.combatDefinition=testCombat;u.Initialize();u.transform.position=new Vector3(100,100);c.transform.position=u.transform.position+Vector3.right*.5f;c.ownerId="B";c.Initialize();float hp=c.Health;world.Tick(.1f);Check(c.Health<hp&&u.State==ArmyBattleState.Engaged,"collector attack uses battle lock and health damage");Check(world.RequestEscape(u),"attacker can escape collector engagement");Check(c.ownerId=="B","collector attack never captures ownership");UnityEngine.Object.DestroyImmediate(testCombat);if(rebuilt!=null)UnityEngine.Object.DestroyImmediate(rebuilt.gameObject);UnityEngine.Object.DestroyImmediate(created.gameObject);UnityEngine.Object.DestroyImmediate(root);live.world.setup.modes.SetMode(MouseCommandMode.Interaction);
        }
    }
}





